code.default:
try:
    import datetime
    import re
    import json
    flow = str(vars.get('flow_kind', 'payment'))
    vars['validation_route'] = 'callback' if flow == 'callback' else 'collection'
    vars['negotiation_instruction'] = 'Ask for the missing precise value; no bank write is permitted.'
    vars['callback_ready'] = 'no'
    vars.setdefault('callback_validated_date', '')
    vars.setdefault('callback_validated_time', '')
    vars['validated_amount'] = ''
    vars['validated_date'] = ''
    now = datetime.datetime.fromisoformat(str(vars.get('now', '')).replace('Z', '+00:00')).replace(tzinfo=None)
    today = now.date()
    holidays = set(['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01'])
    weekdays = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']
    def business(day):
        return day.weekday() < 5 and day.isoformat() not in holidays
    def next_business(day):
        day = day + datetime.timedelta(days=1)
        while not business(day):
            day = day + datetime.timedelta(days=1)
        return day
    def parse_day(value):
        text = str(value).strip().lower()
        if text == 'today':
            return today
        if text == 'tomorrow':
            return today + datetime.timedelta(days=1)
        if text in ['day after tomorrow', 'the day after tomorrow']:
            return today + datetime.timedelta(days=2)
        match = re.fullmatch(r'(this|next)\s+(monday|tuesday|wednesday|thursday|friday|saturday|sunday)', text)
        if match:
            monday = today - datetime.timedelta(days=today.weekday())
            return monday + datetime.timedelta(days=weekdays.index(match.group(2)) + (7 if match.group(1) == 'next' else 0))
        if re.fullmatch(r'\d{4}-\d{2}-\d{2}', text):
            return datetime.date.fromisoformat(text)
        for form in ['%d %B %Y', '%B %d %Y', '%d %b %Y', '%b %d %Y']:
            try:
                cleaned = re.sub(r'(\d)(st|nd|rd|th)', r'\1', text).replace(',', '')
                return datetime.datetime.strptime(cleaned, form).date()
            except Exception:
                pass
        return None
    if flow == 'callback':
        date_text = str(vars.get('callback_date_expression', '')).strip()
        time_text = str(vars.get('callback_time_expression', '')).strip()
        day = parse_day(date_text)
        match = re.fullmatch(r'(\d{1,2}):(\d{2})', time_text)
        if not date_text or not time_text or day is None or not match:
            vars['negotiation_instruction'] = 'Ask only for the missing or ambiguous callback date/time. Use an explicit calendar date and unambiguous time; do not schedule yet.'
        else:
            valid_time = int(match.group(1)) < 24 and int(match.group(2)) < 60
            stamp = datetime.datetime.combine(day, datetime.time(int(match.group(1)), int(match.group(2)))) if valid_time else now
            next_day = next_business(today)
            valid = valid_time and day in [today, next_day] and datetime.time(10, 0) <= stamp.time() <= datetime.time(19, 0) and stamp > now
            if valid:
                vars['callback_validated_date'] = day.isoformat()
                vars['callback_validated_time'] = stamp.strftime('%H:%M')
                vars['callback_ready'] = 'yes'
                vars['negotiation_instruction'] = 'Immediately call schedule_callback with the validated date ' + day.isoformat() + ' and time ' + stamp.strftime('%H:%M') + '.'
            else:
                count = int(vars.get('callback_invalid_count', 0)) + 1
                vars['callback_invalid_count'] = count
                if count >= 2:
                    vars['validation_route'] = 'closing'
                    vars['final_outcome'] = 'not_reached'
                    vars['final_reason'] = 'no_callback'
                    vars['negotiation_instruction'] = 'No callback may be scheduled after the second invalid proposal. Thank the speaker and say goodbye before closing not_reached/no_callback.'
                else:
                    vars['negotiation_instruction'] = 'That callback is outside the permitted window. Ask once for another time using the calculated callback windows.'
    else:
        full = float(vars.get('past_due', -1))
        floor = float(vars.get('floor', -1))
        deadline = datetime.date.fromisoformat(str(vars.get('deadline', '')))
        event = str(vars.get('review_kind', 'proposal'))
        offer_amount = float(vars.get('offer_amount', full))
        offer_date = str(vars.get('offer_date', today.isoformat()))
        if event == 'refusal' and vars.get('hardship_active') == 'yes':
            vars['negotiation_instruction'] = 'Do not persuade. Offer connection to support if not already offered; acceptance means support transfer, decline means no_promise/hardship.'
        elif event == 'refusal':
            rejected = vars.get('rejected_offers', [])
            if isinstance(rejected, str):
                rejected = json.loads(rejected)
            if not isinstance(rejected, list):
                rejected = []
            pair = [offer_amount, offer_date]
            if pair not in rejected:
                rejected.append(pair)
            vars['rejected_offers'] = rejected
            used = int(vars.get('persuasion_used', 0))
            limit = int(vars.get('attempt_limit', 1))
            chosen = False
            while used < limit and not chosen:
                used += 1
                amount = floor if used == 2 or vars.get('full_too_much') == 'yes' else full
                date = deadline.isoformat() if used == 2 else str(vars.get('attempt_one_date', ''))
                candidate = parse_day(date)
                if [amount, date] not in rejected and candidate is not None and today <= candidate <= deadline and business(candidate):
                    vars['offer_amount'] = amount
                    vars['offer_date'] = date
                    vars['negotiation_instruction'] = 'Persuasion attempt ' + str(used) + ': offer ' + str(amount) + ' on ' + date + '. Ask whether the customer can make that payment.'
                    if amount < full:
                        vars['negotiation_instruction'] += ' Say the rest stays overdue.'
                    chosen = True
            vars['persuasion_used'] = used
            if not chosen:
                vars['validation_route'] = 'closing'
                vars['final_outcome'] = 'no_promise'
                vars['final_reason'] = 'refused'
                vars['negotiation_instruction'] = 'The allowed offers are exhausted. Do not repeat a rejected offer; thank the customer and say goodbye before closing no_promise/refused.'
        elif event == 'full_too_much':
            vars['full_too_much'] = 'yes'
            if vars.get('floor_offered') != 'yes':
                vars['floor_offered'] = 'yes'
                vars['offer_amount'] = floor
                vars['negotiation_instruction'] = 'Offer the floor ' + str(floor) + ' once, for the current proposed date. Say the rest stays overdue. Obtain acceptance; do not record yet.'
            else:
                vars['negotiation_instruction'] = 'The floor was already offered. Do not repeat that offer. If the customer rejects it, process a flat refusal; if they propose a date or amount, validate that proposal.'
        else:
            amount_text = str(vars.get('proposal_amount_text', '')).strip()
            date_text = str(vars.get('proposal_date_expression', '')).strip()
            amount = float(amount_text) if amount_text else offer_amount
            date_text = date_text if date_text else offer_date
            day = parse_day(date_text)
            if not (amount >= 0 and amount < float('inf')):
                vars['negotiation_instruction'] = 'Ask the customer to clarify the payment amount already stated; do not ask how much they can pay.'
            elif amount < floor:
                vars['full_too_much'] = 'yes'
                if vars.get('floor_offered') != 'yes':
                    vars['floor_offered'] = 'yes'
                    vars['offer_amount'] = floor
                    if day is not None:
                        vars['offer_date'] = day.isoformat()
                    vars['negotiation_instruction'] = 'Explain that the proposed amount cannot be recorded. Offer the floor ' + str(floor) + ' once and say the rest stays overdue. Wait for acceptance.'
                else:
                    vars['negotiation_instruction'] = 'Explain that the below-floor amount cannot be recorded. Do not repeat the rejected floor offer; an explicit refusal of the floor is processed as a flat refusal.'
            elif amount > full:
                vars['offer_amount'] = full
                vars['negotiation_instruction'] = 'Explain that the full past-due amount is ' + str(full) + '. Offer that amount and obtain acceptance; do not silently reduce the proposal.'
            elif day is None:
                vars['offer_amount'] = amount
                lower = date_text.lower()
                vague = any(term in lower for term in ['next week', 'end of', 'salary', 'sometime', 'someday', 'when i', 'later', 'soon'])
                if vague:
                    count = int(vars.get('vague_count', 0)) + 1
                    vars['vague_count'] = count
                    if count == 1:
                        vars['negotiation_instruction'] = 'Ask once for the exact payment day. Do not count the vague proposed date as a refusal.'
                    else:
                        vars['offer_date'] = deadline.isoformat()
                        vars['negotiation_instruction'] = 'Propose the deadline ' + deadline.isoformat() + ' for amount ' + str(amount) + ' and obtain acceptance.'
                else:
                    vars['negotiation_instruction'] = 'Ask for the precise payment date or the missing date component. For a bare weekday ask this week or next week. Do not guess or record.'
            elif day < today:
                vars['offer_amount'] = amount
                vars['negotiation_instruction'] = 'Explain that a past payment date cannot be recorded. Ask which precise date from today through ' + deadline.isoformat() + ' is intended.'
            elif day > deadline:
                vars['offer_amount'] = amount
                vars['offer_date'] = deadline.isoformat()
                vars['negotiation_instruction'] = 'Say the latest date you can record is ' + deadline.isoformat() + ' and offer it for ' + str(amount) + '. Wait for acceptance. Refusal of this deadline is a flat refusal.'
            elif not business(day):
                replacement = next_business(day)
                vars['offer_amount'] = amount
                vars['offer_date'] = replacement.isoformat()
                vars['negotiation_instruction'] = 'Explain that the proposed day is not a business day and offer the next business day, ' + replacement.isoformat() + ', for ' + str(amount) + '. Obtain acceptance before read-back; do not silently move the date.'
            else:
                vars['validated_amount'] = amount
                vars['validated_date'] = day.isoformat()
                vars['offer_amount'] = amount
                vars['offer_date'] = day.isoformat()
                vars['validation_route'] = 'confirm'
                vars['negotiation_instruction'] = 'Read back the product, validated amount and validated date and ask Do you confirm? Wait for a fresh clear yes before create_promise.'
        vars['proposal_amount_text'] = ''
        vars['proposal_date_expression'] = ''
except Exception:
    vars['validation_route'] = 'callback' if vars.get('flow_kind') == 'callback' else 'collection'
    vars['callback_ready'] = 'no'
    vars['validated_amount'] = ''
    vars['validated_date'] = ''
    vars['negotiation_instruction'] = 'Ask for the missing or malformed precise value. No bank write is permitted until validation succeeds.'

